import { createStore } from "solid-js";
import { isServer } from "@solidjs/web";

// `@tanstack/solid-query` 6.0.0-rc.0's `useBaseQuery` return, with its server
// branch guarded by `@solidjs/web`'s `isServer`, which a browser host folds
// to `false` (ADR 0166 and 0284). The fold removes the branch that returns
// another object's member.
function useBaseQuery(options) {
  const [state] = createStore({ search: options.search, isError: false, error: null });
  const passthrough = new Set(["error", "isError"]);
  return new Proxy(state, {
    get(target, prop, receiver) {
      if (typeof prop === "symbol") {
        return Reflect.get(target, prop, receiver);
      }
      if (isServer) {
        const resolved = { search: "server" };
        if (prop in resolved) {
          return Reflect.get(resolved, prop);
        }
      }
      if (passthrough.has(prop)) {
        return Reflect.get(target, prop, receiver);
      }
      if (state.isError) {
        throw state.error;
      }
      return Reflect.get(target, prop, receiver);
    }
  });
}
export function useQuery(options) {
  return useBaseQuery(options);
}

// The guard solid-query publishes: `typeof window` is no host constant
// (ADR 0166), so the server branch stays live and the proof refuses.
var isServer2 = typeof window === "undefined";
function useWindowBaseQuery(options) {
  const [state] = createStore({ search: options.search, isError: false, error: null });
  return new Proxy(state, {
    get(target, prop, receiver) {
      if (isServer2) {
        const resolved = { search: "server" };
        if (prop in resolved) {
          return Reflect.get(resolved, prop);
        }
      }
      return Reflect.get(target, prop, receiver);
    }
  });
}
export function useWindowQuery(options) {
  return useWindowBaseQuery(options);
}
